svg.script:
(async () => {
  const expected = new URL('./worker.js', location.href);
  const key = 'xyfer-start:' + location.pathname;
  let timer;
  try {
    if (!navigator.serviceWorker) throw new Error('Unavailable');
    const task = (async () => {
      const registration = await navigator.serviceWorker.register('./worker.js?v=9', { scope: './', updateViaCache: 'none' });
      const worker = registration.installing || registration.waiting || registration.active;
      if (!worker) throw new Error('Unavailable');
      if (worker.state !== 'activated') await new Promise((resolve, reject) => {
        const check = () => { if(worker.state === 'activated') resolve(); else if(worker.state === 'redundant') reject(new Error('Unavailable')); };
        worker.addEventListener('statechange', check); check();
      });
      const channel = new MessageChannel();
      await new Promise((resolve, reject) => {
        channel.port1.onmessage = event => event.data?.type === 'xyfer-ready' ? resolve() : reject(new Error('Unavailable'));
        worker.postMessage({type:'xyfer-check'}, [channel.port2]);
      }).finally(() => { channel.port1.close(); channel.port2.close(); });
      const count = Number(sessionStorage.getItem(key) || 0);
      if (count >= 2) throw new Error('Unavailable');
      sessionStorage.setItem(key, String(count + 1));
      location.reload();
    })();
    await Promise.race([task, new Promise((_,reject) => {timer = setTimeout(() => reject(new Error('Unavailable')),25000);})]);
  } catch {
    const fallback = document.createElementNS('http://www.w3.org/2000/svg','text');
    fallback.setAttribute('x','960'); fallback.setAttribute('y','650'); fallback.setAttribute('text-anchor','middle'); fallback.setAttribute('fill','#d5b8c0'); fallback.setAttribute('font-size','22');
    fallback.textContent = 'Unable to open. Reload to retry.'; document.documentElement.appendChild(fallback);
  } finally { clearTimeout(timer); }
})();
